class LUPrefix:
    def __init__(self, n: int):
        self.uploaded = [False] * (n + 2)
        self.longest_prefix = 0

    def upload(self, video: int) -> None:
        self.uploaded[video] = True
        while self.uploaded[self.longest_prefix + 1]:
            self.longest_prefix += 1

    def longest(self) -> int:
        return self.longest_prefix

class LUPrefix {
private:
    std::vector<bool> uploaded;
    int longest_prefix;

public:
    LUPrefix(int n) : uploaded(n + 2, false), longest_prefix(0) {}

    void upload(int video) {
        uploaded[video] = true;
        while (uploaded[longest_prefix + 1]) {
            longest_prefix++;
        }
    }

    int longest() {
        return longest_prefix;
    }
};

class LUPrefix {
    private boolean[] uploaded;
    private int longestPrefix;

    public LUPrefix(int n) {
        uploaded = new boolean[n + 2];
        longestPrefix = 0;
    }

    public void upload(int video) {
        uploaded[video] = true;
        while (uploaded[longestPrefix + 1]) {
            longestPrefix++;
        }
    }

    public int longest() {
        return longestPrefix;
    }
}

var LUPrefix = function(n) {
    this.uploaded = new Array(n + 2).fill(false);
    this.longestPrefix = 0;
};

LUPrefix.prototype.upload = function(video) {
    this.uploaded[video] = true;
    while (this.uploaded[this.longestPrefix + 1]) {
        this.longestPrefix++;
    }
};

LUPrefix.prototype.longest = function() {
    return this.longestPrefix;
};
